getVersion <- function(date = TRUE) {
  version <- packageVersion("nprcgenekeepr")
  if (date) {
    pkg_date <- sessioninfo::package_info("nprcgenekeepr")
    pkg_date <- pkg_date[["date"]][pkg_date[["package"]] == "nprcgenekeepr"]
    paste0(version, " (", pkg_date, ")")
  } else {
    paste0(version)
  }
}
